// 🟠 ETSY — listados digitales populares y publicados hace poco (API oficial, gratis).
const C = $('Config').first().json;
const items = [], log = [];
const day = Math.floor(Date.now() / 86400000);
const pick = (list, n) => { if (!list?.length) return []; const s = (day * n) % list.length; return Array.from({ length: Math.min(n, list.length) }, (_, i) => list[(s + i) % list.length]); };
const ageDays = (ts) => Math.max(1, (Date.now() / 1000 - ts) / 86400);

if (!C.ETSY_API_KEY || C.ETSY_API_KEY.startsWith('keystring')) {
  log.push('Etsy: sin API key, se omite');
} else {
  for (const kw of pick(C.ETSY_BUSQUEDAS, C.POR_DIA.etsy)) {
    try {
      const r = await this.helpers.httpRequest({
        method: 'GET', url: 'https://openapi.etsy.com/v3/application/listings/active',
        qs: { keywords: kw, sort_on: 'score', limit: 100 }, headers: { 'x-api-key': C.ETSY_API_KEY }, json: true, timeout: 60000,
      });
      let n = 0;
      for (const l of r.results || []) {
        const digital = l.listing_type === 'download' || (l.tags || []).some((t) => /digital|printable|download|template/i.test(t));
        const age = ageDays(l.original_creation_timestamp || l.created_timestamp);
        const favs = l.num_favorers || 0;
        if (!digital || age > C.MAX_DIAS_ETSY || favs < C.MIN_FAVORITOS_ETSY) continue;
        n++;
        items.push({
          source: 'etsy', external_id: String(l.listing_id), url: l.url, title: l.title, keyword: kw,
          snippet: String(l.description || '').slice(0, 700),
          price: l.price ? l.price.amount / l.price.divisor : 0, currency: l.price?.currency_code || '',
          published_at: new Date((l.original_creation_timestamp || l.created_timestamp) * 1000).toISOString(),
          metrics: { favoritos: favs, vistas: l.views || 0, dias: Math.round(age), tags: (l.tags || []).slice(0, 8) },
          trend_score: Math.round((favs * 10 + (l.views || 0)) / age),
        });
      }
      log.push(`Etsy "${kw}": ${n} recientes`);
    } catch (e) { log.push(`Etsy "${kw}": error ${e.message}`); }
  }
}
return [{ json: { items, log } }];

// 🔴 YOUTUBE — vídeos y Shorts recientes que están explotando sobre productos digitales (API oficial, gratis).
const C = $('Config').first().json;
const prev = $input.first().json; const items = prev.items || [], log = prev.log || [];
const day = Math.floor(Date.now() / 86400000);
const pick = (list, n) => { if (!list?.length) return []; const s = (day * n) % list.length; return Array.from({ length: Math.min(n, list.length) }, (_, i) => list[(s + i) % list.length]); };

if (!C.YOUTUBE_API_KEY || C.YOUTUBE_API_KEY.startsWith('AIza...')) {
  log.push('YouTube: sin API key, se omite');
} else {
  const since = new Date(Date.now() - C.MAX_DIAS_POST * 86400000).toISOString();
  const ids = new Map();
  for (const q of pick(C.YOUTUBE_BUSQUEDAS, C.POR_DIA.youtube)) {
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://www.googleapis.com/youtube/v3/search', json: true, timeout: 30000,
        qs: { key: C.YOUTUBE_API_KEY, part: 'snippet', q, type: 'video', order: 'viewCount', publishedAfter: since, maxResults: 25 } });
      for (const v of r.items || []) if (v.id?.videoId) ids.set(v.id.videoId, q);
    } catch (e) { log.push(`YouTube "${q}": error ${e.message}`); }
  }
  // Estadísticas en bloques de 50 (cuesta 1 unidad por bloque)
  const all = [...ids.keys()];
  let n = 0;
  for (let i = 0; i < all.length; i += 50) {
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://www.googleapis.com/youtube/v3/videos', json: true, timeout: 30000,
        qs: { key: C.YOUTUBE_API_KEY, part: 'snippet,statistics', id: all.slice(i, i + 50).join(',') } });
      for (const v of r.items || []) {
        const views = Number(v.statistics?.viewCount || 0), likes = Number(v.statistics?.likeCount || 0), comments = Number(v.statistics?.commentCount || 0);
        const age = Math.max(1, (Date.now() - new Date(v.snippet.publishedAt)) / 86400000);
        if (views < C.MIN_VISTAS_YOUTUBE) continue;
        n++;
        items.push({
          source: 'youtube', external_id: v.id, url: `https://www.youtube.com/watch?v=${v.id}`, keyword: ids.get(v.id) || '',
          title: v.snippet.title, snippet: `${v.snippet.title}\n${String(v.snippet.description || '').slice(0, 600)}`,
          published_at: v.snippet.publishedAt, image: v.snippet.thumbnails?.high?.url || '',
          metrics: { vistas: views, likes, comentarios: comments, canal: v.snippet.channelTitle, dias: Math.round(age) },
          trend_score: Math.round((views + likes * 20 + comments * 30) / age),
        });
      }
    } catch (e) { log.push(`YouTube estadísticas: error ${e.message}`); }
  }
  log.push(`YouTube: ${all.length} vídeos recientes revisados, ${n} con tracción`);
}
return [{ json: { items, log } }];

// 🌐 EXPLORADOR WEB CON IA — Claude busca en internet productos digitales en tendencia (TikTok, Etsy, Hotmart, Instagram…).
// Usa el saldo de la API de Claude: unas 6 búsquedas al día (~0,06 $ + texto).
const C = $('Config').first().json;
const prev = $input.first().json; const items = prev.items || [], log = prev.log || [];
const hash = (s) => { let h = 0; for (const ch of String(s)) h = (Math.imul(31, h) + ch.charCodeAt(0)) | 0; return 'w' + (h >>> 0).toString(36); };

if (!C.EXPLORADOR_WEB || !C.ANTHROPIC_API_KEY || C.ANTHROPIC_API_KEY.startsWith('sk-ant-...')) {
  log.push('Explorador web: desactivado');
} else {
  const hoy = new Date().toISOString().slice(0, 10);
  const prompt = `Hoy es ${hoy}. Investiga en internet qué PRODUCTOS DIGITALES (plantillas, planners, ebooks, prompts, presets, imprimibles, hojas de cálculo, packs, mini cursos, etc.)
se están volviendo tendencia AHORA (lanzados o virales en los últimos 1-3 meses, no clásicos de hace años) en TikTok, Etsy, Hotmart, Instagram, Pinterest o Gumroad.
Prioriza lo que puede venderse a público hispanohablante por 3-10 USD. Usa varias búsquedas distintas (en español e inglés). Evita marcas registradas y "cursos para ganar dinero".
Devuelve SOLO un JSON (sin texto antes ni después) con esta forma:
[{"titulo":"nombre del producto o tipo de producto","url":"enlace donde lo viste (listado, vídeo o artículo)","plataforma":"tiktok|etsy|hotmart|instagram|pinterest|gumroad|otro",
"evidencia":"qué indica que es tendencia: cifras, ranking, fecha","fecha_aprox":"AAAA-MM o vacío","precio":número o 0,"publico":"para quién es"}]
Entre 8 y 15 elementos, sin repetir.`;
  try {
    const body = { model: C.MODELO_EXPLORADOR || C.MODELO_RAPIDO, max_tokens: 8000,
      tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: C.BUSQUEDAS_WEB_MAX || 6 }],
      messages: [{ role: 'user', content: prompt }] };
    let r, searches = 0, text = '';
    // Las búsquedas largas pueden "pausarse": se continúa hasta 4 veces
    for (let turn = 0; turn < 4; turn++) {
      r = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.anthropic.com/v1/messages', json: true, timeout: 240000,
        headers: { 'x-api-key': C.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01' }, body });
      searches += r.usage?.server_tool_use?.web_search_requests || 0;
      text += (r.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
      if (r.stop_reason !== 'pause_turn') break;
      body.messages = [...body.messages, { role: 'assistant', content: r.content }];
    }
    const t = text.replace(/```json|```/g, '');
    if (t.indexOf('[') < 0) throw new Error(`sin lista (stop: ${r.stop_reason}) ${t.slice(0, 80)}`);
    const list = JSON.parse(t.slice(t.indexOf('['), t.lastIndexOf(']') + 1));
    for (const p of list) {
      if (!p?.titulo) continue;
      items.push({
        source: 'web', external_id: hash((p.url || '') + '|' + p.titulo.toLowerCase()), url: p.url || '', keyword: p.plataforma || '',
        title: p.titulo, snippet: `${p.evidencia || ''}\nPúblico: ${p.publico || ''}`, price: Number(p.precio) || 0, currency: 'USD',
        published_at: p.fecha_aprox || '', metrics: { plataforma: p.plataforma || '', evidencia: String(p.evidencia || '').slice(0, 200) },
        trend_score: 100,
      });
    }
    log.push(`Explorador web: ${list.length} tendencias encontradas (${searches} búsquedas)`);
  } catch (e) { log.push(`Explorador web: error ${e.message}`); }
}
return [{ json: { items, log } }];

// ⚫ TIKTOK — vídeos recientes con mucho alcance sobre productos digitales (Apify).
const C = $('Config').first().json;
const prev = $input.first().json; const items = prev.items || [], log = prev.log || [];
const day = Math.floor(Date.now() / 86400000);
const pick = (list, n) => { if (!list?.length) return []; const s = (day * n) % list.length; return Array.from({ length: Math.min(n, list.length) }, (_, i) => list[(s + i) % list.length]); };

if (!C.APIFY_TOKEN || C.APIFY_TOKEN.startsWith('apify_api_...')) {
  log.push('TikTok: sin token de Apify, se omite');
} else {
  try {
    const input = {
      searchQueries: pick(C.TIKTOK_BUSQUEDAS, C.POR_DIA.tiktok), hashtags: pick(C.TIKTOK_HASHTAGS, C.POR_DIA.tiktok_hashtags),
      resultsPerPage: C.RESULTADOS_POR_BUSQUEDA, searchSection: '/video',
      shouldDownloadVideos: false, shouldDownloadCovers: false, shouldDownloadSubtitles: false, shouldDownloadSlideshowImages: false,
    };
    const res = await this.helpers.httpRequest({
      method: 'POST', url: `https://api.apify.com/v2/acts/clockworks~tiktok-scraper/run-sync-get-dataset-items?token=${C.APIFY_TOKEN}&timeout=280`,
      body: input, json: true, timeout: 300000,
    });
    let n = 0;
    for (const v of res || []) {
      const created = v.createTimeISO ? new Date(v.createTimeISO) : v.createTime ? new Date(v.createTime * 1000) : null;
      if (!created || !v.id) continue;
      const age = Math.max(1, (Date.now() - created) / 86400000);
      const plays = v.playCount || 0;
      if (age > C.MAX_DIAS_POST || plays < C.MIN_VISTAS_TIKTOK) continue;
      n++;
      items.push({
        source: 'tiktok', external_id: String(v.id), url: v.webVideoUrl || '', keyword: v.searchQuery || v.input || '',
        title: String(v.text || '').slice(0, 160), snippet: String(v.text || '').slice(0, 700),
        published_at: created.toISOString(), image: v.videoMeta?.coverUrl || '',
        metrics: { vistas: plays, likes: v.diggCount || 0, compartidos: v.shareCount || 0, guardados: v.collectCount || 0,
          comentarios: v.commentCount || 0, autor: v.authorMeta?.name || '', seguidores: v.authorMeta?.fans || 0, dias: Math.round(age) },
        trend_score: Math.round((plays + 20 * (v.shareCount || 0) + 10 * (v.collectCount || 0)) / age),
      });
    }
    log.push(`TikTok: ${(res || []).length} vídeos revisados, ${n} recientes y virales`);
  } catch (e) { log.push(`TikTok: error ${e.message}`); }
}
return [{ json: { items, log } }];

// 🟣 INSTAGRAM — publicaciones/reels recientes de hashtags de productos digitales (Apify).
const C = $('Config').first().json;
const prev = $input.first().json; const items = prev.items || [], log = prev.log || [];
const day = Math.floor(Date.now() / 86400000);
const pick = (list, n) => { if (!list?.length) return []; const s = (day * n) % list.length; return Array.from({ length: Math.min(n, list.length) }, (_, i) => list[(s + i) % list.length]); };

if (!C.APIFY_TOKEN || C.APIFY_TOKEN.startsWith('apify_api_...')) {
  log.push('Instagram: sin token de Apify, se omite');
} else {
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST', url: `https://api.apify.com/v2/acts/apify~instagram-hashtag-scraper/run-sync-get-dataset-items?token=${C.APIFY_TOKEN}&timeout=280`,
      body: { hashtags: pick(C.INSTAGRAM_HASHTAGS, C.POR_DIA.instagram), resultsLimit: C.RESULTADOS_POR_BUSQUEDA }, json: true, timeout: 300000,
    });
    let n = 0;
    for (const p of res || []) {
      const created = p.timestamp ? new Date(p.timestamp) : null;
      if (!created || !(p.id || p.shortCode)) continue;
      const age = Math.max(1, (Date.now() - created) / 86400000);
      if (age > C.MAX_DIAS_POST) continue;
      const likes = p.likesCount > 0 ? p.likesCount : 0, comments = p.commentsCount || 0, views = p.videoViewCount || p.videoPlayCount || 0;
      if (likes + comments * 3 + views / 10 < 300) continue;
      n++;
      items.push({
        source: 'instagram', external_id: String(p.id || p.shortCode), url: p.url || `https://www.instagram.com/p/${p.shortCode}/`,
        keyword: (p.inputUrl || '').split('/tags/')[1]?.replace(/\/$/, '') || '',
        title: String(p.caption || '').slice(0, 160), snippet: String(p.caption || '').slice(0, 700),
        published_at: created.toISOString(), image: p.displayUrl || '',
        metrics: { likes, comentarios: comments, vistas: views, autor: p.ownerUsername || '', dias: Math.round(age) },
        trend_score: Math.round((likes + 3 * comments + views / 10) / age),
      });
    }
    log.push(`Instagram: ${(res || []).length} publicaciones revisadas, ${n} recientes con tracción`);
  } catch (e) { log.push(`Instagram: error ${e.message}`); }
}
return [{ json: { items, log } }];

// 🔥 HOTMART — productos "calientes" del marketplace por palabra clave (Apify).
const C = $('Config').first().json;
const prev = $input.first().json; const items = prev.items || [], log = prev.log || [];
const day = Math.floor(Date.now() / 86400000);
const pick = (list, n) => { if (!list?.length) return []; const s = (day * n) % list.length; return Array.from({ length: Math.min(n, list.length) }, (_, i) => list[(s + i) % list.length]); };

if (!C.APIFY_TOKEN || C.APIFY_TOKEN.startsWith('apify_api_...')) {
  log.push('Hotmart: sin token de Apify, se omite');
} else {
  try {
    const kws = pick(C.HOTMART_BUSQUEDAS, C.POR_DIA.hotmart);
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.apify.com/v2/acts/jungle_synthesizer~hotmart-marketplace-product-catalog-scraper/run-sync-get-dataset-items?token=${C.APIFY_TOKEN}&timeout=280`,
      body: { keywords: kws, maxItems: kws.length * 24 }, json: true, timeout: 300000,
    });
    for (const p of res || []) {
      const url = p.product_url || p.url || p.marketplace_url || '';
      const id = p.product_id || p.id || p.ucode || url;
      if (!id) continue;
      // Hotmart no da fecha de publicación: priorizamos "hot_score" alto con pocas reseñas (señal de producto nuevo que despega).
      const reviews = p.rating_count || 0, hot = p.hot_score || 0;
      items.push({
        source: 'hotmart', external_id: String(id), url, keyword: p.search_keyword || '',
        title: p.name || p.product_name || p.title || '', snippet: String(p.description_short || p.description || '').slice(0, 700),
        price: p.price || p.price_brl || 0, currency: p.currency || (p.price_brl ? 'BRL' : ''), image: p.thumbnail_url || '',
        published_at: '', metrics: { hot_score: hot, reseñas: reviews, nota: p.rating_avg || 0, formato: p.format || '', autor: p.producer_name || '' },
        trend_score: Math.round(hot / Math.log10(reviews + 10)),
      });
    }
    log.push(`Hotmart: ${(res || []).length} productos revisados`);
  } catch (e) { log.push(`Hotmart: error ${e.message}`); }
}
return [{ json: { items, log } }];

// 🧮 FILTRAR Y GUARDAR — se queda con lo mejor de cada fuente y lo guarda en la tienda.
// La tienda devuelve solo lo NUEVO (lo que ya vimos otro día no se repite).
const C = $('Config').first().json;
const { items = [], log = [] } = $input.first().json;

const bySource = {};
for (const it of items) (bySource[it.source] ||= []).push(it);
const top = [];
for (const [src, list] of Object.entries(bySource)) {
  const seen = new Set();
  const uniq = list.filter((i) => !seen.has(i.external_id) && seen.add(i.external_id));
  uniq.sort((a, b) => b.trend_score - a.trend_score);
  top.push(...uniq.slice(0, C.TOP_POR_FUENTE[src] || 10));
}

let fresh = [];
if (top.length) {
  const r = await this.helpers.httpRequest({
    method: 'POST', url: `${C.TIENDA_URL}/api/n8n/candidates`, headers: { 'x-api-key': C.TIENDA_API_KEY },
    body: { items: top }, json: true, timeout: 60000,
  });
  fresh = r.items || [];
}
log.push(`Total encontrado: ${items.length} · mejores: ${top.length} · nuevos hoy: ${fresh.length}`);
return [{ json: { fresh, log, found: items.length } }];

// 🤖 EVALUAR CON IA — Claude analiza cada hallazgo nuevo y decide si vale la pena.
const C = $('Config').first().json;
const { fresh = [], log = [], found = 0 } = $input.first().json;

const SYSTEM = `Eres analista de productos digitales para una tienda online en español (Latinoamérica y España) que vende con anuncios de Meta.
Recibes un hallazgo (un listado de Etsy/Hotmart o una publicación de TikTok/Instagram) y devuelves SOLO un JSON válido, sin texto extra:
{
 "es_producto_digital": true|false,
 "producto": "qué se vende exactamente, en una frase",
 "titulo": "título atractivo en español para nuestra tienda (máx. 70 caracteres)",
 "frase_corta": "beneficio principal en una frase (máx. 110 caracteres)",
 "descripcion": "descripción de venta en español, 90-160 palabras: para quién es, qué incluye, formato, cómo se usa",
 "categoria": "Plantillas|Productividad|Ebooks|IA|Fotografía|Educación|Finanzas|Negocios|Hogar|Infantil|Otros",
 "emoji": "un emoji",
 "precio_sugerido": número en USD entre 3 y 29,
 "decision": "comprar_reventa" | "recrear" | "descartar",
 "derechos": "si el original menciona PLR/MRR/derechos de reventa, dilo; si no, 'sin derechos de reventa: recrear con contenido propio'",
 "por_que": "por qué está en tendencia ahora (máx. 160 caracteres)",
 "como_recrear": ["3 a 5 ideas concretas para hacer una versión propia MEJOR y distinta"],
 "riesgos": "marcas registradas, copyright, promesas de dinero/salud que Meta rechaza, o 'ninguno'",
 "anuncio": {"gancho": "primera frase de un vídeo/reel", "texto": "texto principal del anuncio (máx. 300 caracteres)", "titular": "máx. 40 caracteres"},
 "nota": número 1-10
}
Criterios de la nota: demanda real y reciente (no productos de hace años), que se pueda vender a hispanohablantes, que se pueda recrear o revender legalmente,
margen con precio bajo (impulso), facilidad para anunciar en Meta. Pon nota ≤4 y decision "descartar" si: no es un producto digital, usa marcas/personajes
con copyright, promete dinero fácil o resultados de salud, es un "curso MRR de marketing digital" tipo esquema, o es contenido personal sin producto.
Solo pon "comprar_reventa" si hay señales claras de licencia PLR/MRR/reventa.
Si el hallazgo es un VÍDEO o PUBLICACIÓN (YouTube, TikTok, Instagram) que habla de vender productos digitales, NO lo descartes por ser un vídeo:
extrae el producto concreto que muestra o recomienda (ej. "plantillas Canva para bodas", "planner de lectura") y evalúa ESE producto.
Solo descarta si el vídeo no menciona ningún producto concreto. Sé conciso: la descripcion máximo 120 palabras. Responde únicamente con el JSON.`;

// Saca el JSON de la respuesta aunque venga con ```json o texto alrededor
const parseJson = (text) => {
  const t = String(text || '').replace(/```json|```/g, '');
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a < 0 || b <= a) throw new Error('la IA no devolvió JSON: ' + t.slice(0, 80));
  return JSON.parse(t.slice(a, b + 1));
};

const out = [];
// Analiza de 5 en 5 a la vez (y como máximo MAX_EVALUAR por día) para terminar rápido
const evaluar = async (c) => {
  try {
    const r = await this.helpers.httpRequest({
      method: 'POST', url: 'https://api.anthropic.com/v1/messages', json: true, timeout: 90000,
      headers: { 'x-api-key': C.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01' },
      body: {
        model: C.MODELO_RAPIDO, max_tokens: 3000, system: SYSTEM,
        messages: [{ role: 'user', content: JSON.stringify({ fuente: c.source, palabra_clave: c.keyword, titulo: c.title, texto: c.snippet,
          precio: c.price, moneda: c.currency, publicado: c.published_at, metricas: c.metrics, url: c.url }) }],
      },
    });
    const text = (r.content || []).map((b) => b.text || '').join('');
    if (r.stop_reason === 'max_tokens') throw new Error('respuesta cortada (max_tokens)');
    const ai = parseJson(text);
    const nota = Number(ai.nota) || 0;
    await this.helpers.httpRequest({
      method: 'POST', url: `${C.TIENDA_URL}/api/n8n/candidates/${c.id}`, headers: { 'x-api-key': C.TIENDA_API_KEY }, json: true,
      body: { ai_score: nota, ai, status: ai.decision === 'descartar' || !ai.es_producto_digital ? 'discarded' : 'new' },
    });
    out.push({ ...c, ai, ai_score: nota });
  } catch (e) { log.push(`IA #${c.id}: error ${e.message}`); }
};
const todo = fresh.slice(0, C.MAX_EVALUAR || 20);
for (let i = 0; i < todo.length; i += 5) await Promise.all(todo.slice(i, i + 5).map(evaluar));
log.push(`Evaluados por la IA: ${out.length}`);
return [{ json: { evaluated: out, log, found } }];

// 📲 AVISAR POR TELEGRAM — te manda los mejores con botones para decidir.
const C = $('Config').first().json;
const { evaluated = [], log = [], found = 0 } = $input.first().json;
const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${C.TELEGRAM_RADAR_TOKEN}/${method}`, body, json: true });
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[ch]));
const icon = { youtube: '🔴 YouTube', web: '🌐 Web', etsy: '🟠 Etsy', tiktok: '⚫ TikTok', instagram: '🟣 Instagram', hotmart: '🔥 Hotmart' };
const num = (n) => Number(n || 0).toLocaleString('es');

const winners = evaluated
  .filter((c) => c.ai_score >= C.NOTA_MINIMA_AVISO && c.ai?.es_producto_digital && c.ai?.decision !== 'descartar')
  .sort((a, b) => b.ai_score - a.ai_score || b.trend_score - a.trend_score)
  .slice(0, 10);

for (const c of winners) {
  const m = c.metrics || {}, ai = c.ai;
  const stats = c.source === 'etsy' ? `❤️ ${num(m.favoritos)} favoritos · publicado hace ${m.dias} días`
    : c.source === 'web' ? `${m.plataforma || ''} · ${m.evidencia || ''}`
    : c.source === 'hotmart' ? `🔥 temperatura ${num(m.hot_score)} · ${num(m.reseñas)} reseñas`
    : `${m.vistas ? `👁 ${num(m.vistas)} vistas · ` : ''}❤️ ${num(m.likes)} · hace ${m.dias} días`;
  const text = `📡 <b>${ai.nota}/10 · ${esc(ai.titulo)}</b>
${icon[c.source] || c.source} · ${stats}

📦 ${esc(ai.producto)}
📈 ${esc(ai.por_que)}
🔑 ${esc(ai.derechos)}
⚠️ Riesgos: ${esc(ai.riesgos)}
💲 Precio sugerido: <b>$${ai.precio_sugerido}</b>
👉 Sugerencia: <b>${ai.decision === 'comprar_reventa' ? 'Comprar y revender' : 'Recrear versión propia'}</b>`;
  try {
    await tg('sendMessage', {
      chat_id: C.TELEGRAM_CHAT_ID, text, parse_mode: 'HTML', link_preview_options: { is_disabled: true },
      reply_markup: { inline_keyboard: [
        [{ text: '🛒 Comprar y revender', callback_data: `buy:${c.id}` }, { text: '🛠️ Recrear', callback_data: `rec:${c.id}` }],
        [{ text: '❌ Descartar', callback_data: `no:${c.id}` }, ...(c.url ? [{ text: '🔗 Ver original', url: c.url }] : [])],
      ] },
    });
    await this.helpers.httpRequest({ method: 'POST', url: `${C.TIENDA_URL}/api/n8n/candidates/${c.id}`, headers: { 'x-api-key': C.TIENDA_API_KEY }, body: { status: 'notified' }, json: true });
  } catch (e) { log.push(`Telegram #${c.id}: ${e.message}`); }
}

await tg('sendMessage', {
  chat_id: C.TELEGRAM_CHAT_ID, parse_mode: 'HTML',
  text: `🗞️ <b>Radar de hoy</b>\nRevisados: ${found} · Evaluados: ${evaluated.length} · Te avisé: ${winners.length}\n\n<code>${esc(log.join('\n')).slice(0, 3000)}</code>`,
});
return [{ json: { avisados: winners.length, log } }];
